def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Endgame exploitation: in the last few rounds it is safer to defect
    # unless the opponent has been perfectly cooperative and we want the
    # small extra mutual cooperation payoff.
    if n >= 97:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_d = sum(1 for a in opp if a == 'D')
    opp_c = n - opp_d

    last_me, last_opp = history[-1]

    # Count consecutive defections by the opponent at the end.
    cons_opp_d = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            cons_opp_d += 1
        else:
            break

    # Count consecutive cooperations by the opponent at the end.
    cons_opp_c = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'C':
            cons_opp_c += 1
        else:
            break

    # Early rounds: be cooperative but retaliate immediately against early
    # defection.  This handles TFT-like opponents and probes without creating
    # long retaliation chains.
    if n < 5:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Against an always-defector, defect.  A rare probe is kept to catch
    # opponents that might switch phases, but the low probability avoids
    # giving away score.
    if opp_d >= n - 1:
        if n > 12 and rng.random() < 0.04:
            return 'C'
        return 'D'

    # If the opponent has been almost perfectly cooperative, maintain
    # cooperation for the long mutual-cooperation payoff.  Very rare late
    # probes can exploit pure cooperators without much risk.
    if opp_d <= 1:
        if n >= 70 and rng.random() < 0.03:
            return 'D'
        return 'C'

    # If we have both been locked into mutual defection for several rounds,
    # make a controlled cooperation attempt to escape the death spiral.
    if last_me == 'D' and last_opp == 'D':
        if cons_opp_d >= 2:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated.
    if last_opp == 'C':
        # If the opponent has a history of frequent defection, remain cautious
        # but generally reward cooperation.
        if opp_d * 3 > n * 2:
            if rng.random() < 0.30:
                return 'D'
            return 'C'
        return 'C'

    # Opponent just defected.
    if last_opp == 'D':
        # A single defection after a long cooperative run is likely a probe or
        # a retaliation.  Punish once, but forgive quickly.
        if cons_opp_d == 1 and opp_d * 4 < n:
            return 'D'
        # Longer defection streak: defend.
        if cons_opp_d >= 3:
            if rng.random() < 0.10:
                return 'C'
            return 'D'
        # Medium streak: mostly defect, with a chance to restore cooperation.
        if rng.random() < 0.20:
            return 'C'
        return 'D'

    return 'C'
